INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(60012,0,0,'Maybe I call myself $psfoot from now on.',12,0,100,0,0,0,''),
(60012,0,1,'Many thanks for rescue!',12,0,100,0,0,0,''),
(63535,0,0,'Someone has come to save us? Perhaps all is not lost...',12,0,100,1,0,0,''),
(63542,0,0,'Someone has come to save us? Perhaps all is not lost...',12,0,100,1,0,0,''),
(63751,0,0,'I don\'t know about this \"Horde\", but you look trustworthy. I\'ll gather everyone up and meet you when we\'re ready to rebuild!',12,0,100,1,0,0,''),
(63754,0,0,'I don\'t know about this \"Alliance\", but you look trustworthy. I\'ll gather everyone up and meet you when we\'re ready to rebuild!',12,0,100,1,0,0,''),
(66073,0,0,'Sometimes the best defense is to prevent your opponent from acting against you.',12,0,100,0,0,0,''),
(66073,1,0,'Bow to me and we shall begin.',12,0,100,0,0,0,''),
(66073,2,0,'Your power is impressive.  I admit defeat.',12,0,100,0,0,0,''),
(66149,0,0,'Not all problems can be solved with your fists.  Sometimes you must center yourself and channel your energy towards a distant target.',12,0,100,0,0,0,''),
(66149,1,0,'Bow to me and we shall begin.',12,0,100,0,0,0,''),
(66149,2,0,'I am defeated.',12,0,100,0,0,0,''),
(66180,0,0,'A well-timed application of force to a pressure point will stop an opponent in their tracks, regardless of what they are doing.  Use this to your advantage to avoid dangerous attacks.',12,0,100,0,0,0,''),
(66180,1,0,'Bow to me and we shall begin.',12,0,100,0,0,0,''),
(66180,2,0,'Your power is impressive.  I admit defeat.',12,0,100,0,0,0,''),
(66732,0,0,'To defeat me, you will need to use all that you have learned from the other masters.  If you can do that, your training will be complete.',12,0,100,0,0,0,''),
(66732,1,0,'Bow to me and we shall begin.',12,0,100,0,0,0,''),
(66732,2,0,'Well done.  Your training is now complete.  Come see me in the Shrine of the Ox for your reward.',12,0,100,0,0,0,'');
