INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(72994,0,0,'Be careful. I would not want you to fall into the arena.',12,0,100,0,0,0,''),
(73037,0,0,'Please, come down. How am I ever going to explain this to the rest of the Tillers?',12,0,100,0,0,0,''),
(73037,0,1,'If you fall off, I\'m not going in after you!',12,0,100,0,0,0,''),
(73435,0,0,'Dare ta drink a Dragon P.I.E.! It\'ll put hair on yer chest, and then hair on THAT!',12,0,100,4,0,0,''),
(73435,0,1,'GRUB N\' GROG!',12,0,100,22,0,0,''),
(73435,0,2,'Ye won\'t find anythin\' like it elsewhere. Come and try!',12,0,100,1,0,0,''),
(73435,0,3,'The perfect mix of northern and southern styles!',12,0,100,5,0,0,''),
(73618,0,0,'You there! Come and try some Greenstone Brew!',12,0,100,25,0,0,''),
(73618,0,1,'Greenstone Brew! Straight from the heart of the Jade Forest.',12,0,100,1,0,0,''),
(73618,0,2,'Nothing beats the bold bite of Greenstone Brew!',12,0,100,4,0,0,''),
(73622,0,0,'Delicious food and drink at  reasonable prices!',12,0,100,22,0,0,''),
(73622,0,1,'Hungry? Thirsty? Tired? Let Graceful Swan take care of you!',12,0,100,1,0,0,''),
(73622,0,2,'Come rest your weary feet, adventurer!',12,0,100,3,0,0,''),
(73647,0,0,'Exotic, aromatic, a brew good for both body and spirit!',12,0,100,1,0,0,''),
(73647,0,1,'Brave the brew that\'s truly unique! Invigorating, satisfying... amber-brew!',12,0,100,25,0,0,''),
(73647,0,2,'Exquisite amber-brew from beyond the Serpent\'s Spine!',12,0,100,22,0,0,''),
(73651,0,0,'It\'s Stormstout time!',12,0,100,22,0,0,''),
(73651,0,1,'Stormstout. Probably the best brew in Azeroth.',12,0,100,273,0,0,''),
(73651,0,2,'When you say Stormstout, you\'ve said it all.',12,0,100,1,0,0,''),
(73651,0,3,'If you\'ve got the time, we\'ve got the brew. Stormstout!',12,0,100,6,0,0,''),
(73651,0,4,'Stormstout. Pandaren for \"beer.\"',12,0,100,25,0,0,''),
(73656,0,0,'Arms and armor repaired!',12,0,100,22,0,0,''),
(73656,0,1,'Don\'t be caught unprepared! Let Crafter Kwon see to your gear!',12,0,100,396,0,0,''),
(73656,0,2,'Blades sharpened! Armor mended!',12,0,100,22,0,0,''),
(73657,0,0,'Come, sit down, enjoy a meal!',12,0,100,70,0,0,''),
(73657,0,1,'Delicious dishes and fresh-made island delicacies!',12,0,100,22,0,0,''),
(73657,0,2,'For the finest food, look no further!',12,0,100,396,0,0,''),
(73812,0,0,'Steaming goat noodle: NUMBER ONE!',12,0,100,51,0,0,''),
(73812,0,1,'Come fill belly with noodle, yes! Very good!',12,0,100,1,0,0,''),
(73812,0,2,'Noodle so tasty! You come try, yes?',12,0,100,1,0,0,''),
(73813,0,0,'Please try my Harmonious River Noodles. They will not disappoint.',12,0,100,2,0,0,''),
(73813,0,1,'Fresh fish, caught within the hour! ...I think? Curse this island.',12,0,100,1,0,0,''),
(73813,0,2,'River style noodles, made with only the freshest fish.',12,0,100,3,0,0,''),
(73813,0,3,'Harmonious River Noodles!',12,0,100,22,0,0,''),
(73814,0,0,'Monmon study MANY weeks with master noodle chef.',12,0,100,1,0,0,''),
(73814,0,1,'I got good noodles here!',12,0,100,3,0,0,''),
(73814,0,2,'BUY NOODLES!',12,0,100,4,0,0,''),
(73815,0,0,'HOT AND HEARTY! Come try Yaungolian noodles!',12,0,100,5,0,0,''),
(73815,0,1,'Bold flavor, bold heat! No other noodles come close!',12,0,100,1,0,0,''),
(73815,0,2,'Why settle for weak, flavorless noodles? Try them yaungolian style!',12,0,100,6,0,0,''),
(73816,0,0,'You will find only the best noodles in all Pandaria here.',12,0,100,1,0,0,''),
(73816,0,1,'Please come enjoy my fine Golden Dragon Noodles.',12,0,100,2,0,0,''),
(73816,0,2,'Golden Dragon Noodles! The very BEST!',12,0,100,22,0,0,''),
(73817,0,0,'So tasty! So delicious! Double Lucky special noodles!',12,0,100,396,0,0,''),
(73817,0,1,'Hey hey! Come here, have some tasty noodles!',12,0,100,3,0,0,''),
(73817,0,2,'Yoo-hoo! Come try some Lucky Mushroom Noodles?',12,0,100,24,0,0,''),
(73817,0,3,'Lucky-Lucky! Come have some noodles!',12,0,100,22,0,0,'');
